package com.drogaria.backend.controller;
import com.drogaria.backend.dto.*; import com.drogaria.backend.service.CupomService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/cupom") public class CupomController { private final CupomService s; public CupomController(CupomService s){this.s=s;} @GetMapping public List<CupomResponse> listar(){return s.listar();} @GetMapping("/{id}") public CupomResponse buscar(@PathVariable Integer id){return s.buscar(id);} @GetMapping("/codigo/{codigo}") public CupomResponse codigo(@PathVariable String codigo){return s.listar().stream().filter(c->c.getCodigo().equalsIgnoreCase(codigo)).findFirst().orElseThrow(()->new com.drogaria.backend.exception.ApiException("Cupom nao encontrado",HttpStatus.NOT_FOUND));} @PostMapping public ResponseEntity<CupomResponse> salvar(@Valid @RequestBody CupomRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.salvar(r));} @PutMapping("/{id}") public CupomResponse atualizar(@PathVariable Integer id,@Valid @RequestBody CupomRequest r){return s.atualizar(id,r);} @DeleteMapping("/{id}") public ResponseEntity<Void> excluir(@PathVariable Integer id){s.excluir(id);return ResponseEntity.noContent().build();} }